module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_in    ,

    output  reg         valid_out     ,
    output  reg [9:0]   data_out
);

reg [1:0] count;             // Counter for number of valid inputs (counts up to 4)
reg [9:0] sum;               // Accumulated sum of inputs
reg valid_out_d;             // Register to generate valid_out pulse

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        count <= 2'd0;
        sum <= 10'd0;
        valid_out <= 1'b0;
        data_out <= 10'd0;
        valid_out_d <= 1'b0;
    end else begin
        valid_out <= 1'b0;  // Default to low, set high only when count reaches 4
        if (valid_in) begin
            sum <= sum + data_in;  // Accumulate data_in
            count <= count + 1'b1;
            if (count == 2'd3) begin
                // When count was 3, after increment it becomes 4
                // Output the result
                data_out <= sum + data_in; // sum + current data_in
                valid_out <= 1'b1; // Set valid_out high for one cycle
                // Reset sum and count for next sequence
                sum <= 10'd0;
                count <= 2'd0;
            end
        end
    end
end

endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_in    ,

    output  reg         valid_out     ,
    output  reg [9:0]   data_out
);

reg [1:0] count;           // Counter for number of valid inputs (0 to 4)
reg [9:0] sum;             // Accumulated sum

// Sequential logic for accumulation and counting
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        count <= 2'd0;
        sum <= 10'd0;
        valid_out <= 1'b0;
        data_out <= 10'd0;
    end else begin
        // Clear valid_out at start of cycle
        valid_out <= 1'b0;

        if (valid_in) begin
            sum <= sum + {2'b00, data_in}; // zero-extend data_in to 10 bits
            count <= count + 1'b1;
        end

        if (count == 2'd3 && valid_in) begin
            // After receiving 4 valid inputs (count from 0 to 3)
            data_out <= sum + {2'b00, data_in}; // Assign final sum
            valid_out <= 1'b1;
            // Reset for next cycle
            count <= 2'd0;
            sum <= 10'd0;
        end else if (valid_in) begin
            // Continue accumulating
            // sum and count are already updated above
        end
    end
end

endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_in     ,

    output  reg         valid_out     ,
    output  reg [9:0]   data_out
);

reg [9:0] sum;           // Accumulated sum
reg [1:0] count;         // Counter for valid inputs (counts up to 4)
reg valid_out_reg;       // Internal register for valid_out

// Synchronous reset and accumulation logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum <= 10'b0;
        count <= 2'b0;
        valid_out <= 1'b0;
        data_out <= 10'b0;
    end else begin
        // Clear valid_out at the start of each cycle
        valid_out <= 1'b0;

        if (valid_in) begin
            // Add data_in to sum
            sum <= sum + {2'b00, data_in}; // zero-extend to 10 bits
            count <= count + 1;

            if (count == 2'd3) begin
                // When 4 valid inputs are received
                data_out <= sum + {2'b00, data_in}; // Final sum before reset
                valid_out <= 1'b1; // Assert valid_out for one cycle
                sum <= 10'b0; // Reset sum for next sequence
                count <= 2'b0; // Reset counter
            end
        end
    end
end
endmodule

module accu(
    input               clk         ,   
