    input               valid_in     ,

    output  reg         valid_out     ,
    output  reg [9:0]   data_out
);

reg [1:0] count;          // Counter for number of valid inputs (0 to 4)
reg [9:0] sum;            // Accumulated sum

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        count <= 2'b00;
        sum <= 10'b0;
        valid_out <= 1'b0;
        data_out <= 10'b0;
    end else begin
        // Clear valid_out at start of cycle
        valid_out <= 1'b0;
        if (valid_in) begin
            sum <= sum + data_in;
            count <= count + 1;
            if (count == 2'b11) begin
                // When count reaches 4 (since count starts from 0)
                data_out <= sum + data_in; // Final sum includes current data_in
                valid_out <= 1'b1;
                count <= 2'b00;
                sum <= 10'b0;
            end
        end
    end
end

endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_in    ,

    output  reg         valid_out     ,
    output  reg [9:0]   data_out
);

reg [1:0] count;            // Counter for number of valid inputs received (max 4)
reg [9:0] sum;              // Accumulated sum

initial begin
    count = 2'b00;
    sum = 10'b0;
    valid_out = 1'b0;
    data_out = 10'b0;
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        count <= 2'b00;
        sum <= 10'b0;
        valid_out <= 1'b0;
        data_out <= 10'b0;
    end else begin
        valid_out <= 1'b0; // Default, valid_out high only for one cycle when count reaches 4
        if (valid_in) begin
            sum <= sum + data_in;
            count <= count + 1'b1;
        end

        if (count == 2'd3 && valid_in) begin
            // When the third valid input is just received, next will be the fourth
            // So, after adding the fourth, we output
            // But since counting from zero, after incrementing count to 3, next valid_in will be the fourth
            // To handle this, check if count == 3 and valid_in is high in this cycle
            // Actually, to simplify, trigger output when count reaches 4
            // But since count is incremented after adding data, check for count == 3 before increment
        end

        // To precisely trigger output after receiving 4 valid inputs
        if (count == 2'd3 && valid_in) begin
            data_out <= sum + data_in; // Final sum including current data_in
            valid_out <= 1'b1;         // Signal valid output
            // Reset for next sequence
            count <= 2'b00;
            sum <= 10'b0;
        end
    end
end

endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_in     ,

    output  reg         valid_out     ,
    output  reg [9:0]   data_out
);

reg [9:0] sum;          // Accumulated sum
reg [1:0] count;        // Count of valid inputs (0 to 4)
reg valid_out_d;        // Delayed valid_out for one-cycle pulse

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum <= 10'd0;
        count <= 2'd0;
        valid_out <= 1'b0;
        data_out <= 10'd0;
        valid_out_d <= 1'b0;
    end else begin
        valid_out <= 1'b0;  // Default, will set to 1 only when count reaches 4
        if (valid_in) begin
            sum <= sum + data_in;
            count <= count + 1;
        end
        if (count == 2'd3 && valid_in) begin
            // After receiving the 4th valid input
            data_out <= sum + data_in; // Final sum including current data_in
            valid_out <= 1'b1;         // Set valid_out high for this cycle
            // Reset for next accumulation
            sum <= 10'd0;
            count <= 2'd0;
        end
    end
end

endmodule

module accu(
