    output  reg         valid_out     ,
    output  reg [9:0]   data_out
);

reg [1:0] count;             // Counter for number of valid inputs (0 to 4)
reg [9:0] sum;               // Accumulated sum

// Sequential logic for accumulation and state management
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        count <= 2'd0;
        sum <= 10'd0;
        valid_out <= 1'b0;
        data_out <= 10'd0;
    end else begin
        // Clear valid_out at the start of each cycle
        valid_out <= 1'b0;

        if (valid_in) begin
            sum <= sum + {2'b00, data_in}; // Extend data_in to 10 bits before addition
            count <= count + 1'b1;
        end

        // When four valid inputs are received
        if (count == 2'd3 && valid_in) begin
            data_out <= sum + {2'b00, data_in}; // Output the final sum
            valid_out <= 1'b1; // Indicate valid output
            // Reset for next accumulation
            count <= 2'd0;
            sum <= 10'd0;
        end else if (count != 2'd0 && valid_in) begin
            // Continue accumulating
            // sum already updated above
        end else if (count == 2'd0 && valid_in == 1'b0) begin
            // No action needed, wait for valid_in
        end
    end
end

endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_in    ,

    output  reg         valid_out     ,
    output  reg [9:0]   data_out
);

reg [9:0] sum;            // 10-bit accumulator
reg [1:0] count;          // 2-bit counter for 4 inputs (0 to 3)
reg valid_out_d;          // delayed valid_out signal for one-cycle pulse

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum <= 10'd0;
        count <= 2'd0;
        valid_out <= 1'b0;
        valid_out_d <= 1'b0;
        data_out <= 10'd0;
    end else begin
        valid_out <= 1'b0; // default, will set high when condition met
        valid_out_d <= valid_out; // track previous valid_out for one-cycle pulse

        if (valid_in) begin
            sum <= sum + {2'b00, data_in}; // zero-extend data_in to 10 bits
            count <= count + 1'b1;
        end

        if (count == 2'd3 && valid_in) begin
            // When 4 inputs have been accumulated
            data_out <= sum + {2'b00, data_in}; // final sum including current data_in
            valid_out <= 1'b1; // set valid_out high for one cycle
            // reset for next accumulation
            sum <= 10'd0;
            count <= 2'd0;
        end else if (valid_in) begin
            // continue accumulating
            sum <= sum + {2'b00, data_in};
        end
    end
end

endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_in    ,

    output  reg         valid_out     ,
    output  reg [9:0]   data_out
);

reg [9:0] sum;           // Accumulated sum
reg [1:0] count;         // Count of valid inputs (max 4)
reg valid_out_d;         // Delayed valid_out for one cycle

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum <= 10'd0;
        count <= 2'd0;
        valid_out <= 1'b0;
        data_out <= 10'd0;
        valid_out_d <= 1'b0;
    end else begin
        if (valid_in) begin
            sum <= sum + {2'b00, data_in}; // Extend data_in to 10 bits
            count <= count + 1'b1;
        end

        if (count == 2'd3 && valid_in) begin
            // This is the 4th valid input (count from 0 to 3)
            data_out <= sum + {2'b00, data_in};
            valid_out <= 1'b1;
        end else if (valid_out_d) begin
            // Reset valid_out after one cycle
            valid_out <= 1'b0;
            // Reset sum and count for next sequence
            sum <= 10'd0;
            count <= 2'd0;
        end

        // Delay valid_out to reset it after one cycle
        valid_out_d <= valid_out;
    end
end

endmodule

