reg [1:0] count;        // Count of valid inputs (0 to 4)
reg valid_out_d;        // Internal flag to generate valid_out pulse

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum <= 10'd0;
        count <= 2'd0;
        valid_out <= 1'b0;
        data_out <= 10'd0;
        valid_out_d <= 1'b0;
    end else begin
        if (valid_in) begin
            sum <= sum + {2'b00, data_in}; // zero-extend data_in to 10 bits before addition
            count <= count + 1;
        end

        if (count == 2'd3 && valid_in) begin
            // After receiving the 4th valid input
            data_out <= sum + {2'b00, data_in}; // Final sum for this cycle
            valid_out <= 1'b1; // Set valid_out high for one cycle
            valid_out_d <= 1'b1;
            // Reset sum and count for next sequence
            sum <= 10'd0;
            count <= 2'd0;
        end else if (valid_out_d) begin
            // Clear valid_out after one cycle
            valid_out <= 1'b0;
            valid_out_d <= 1'b0;
        end
    end
end

endmodule

module adder_8bit(
    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout
);

wire [7:0] carry; // Internal wires for carry propagation

// Full adder for bit 0 (LSB)
assign sum[0] = a[0] ^ b[0] ^ cin;
assign carry[0] = (a[0] & b[0]) | (a[0] ^ b[0]) & cin;

// Full adder for bit 1
assign sum[1] = a[1] ^ b[1] ^ carry[0];
assign carry[1] = (a[1] & b[1]) | (a[1] ^ b[1]) & carry[0];

// Full adder for bit 2
assign sum[2] = a[2] ^ b[2] ^ carry[1];
assign carry[2] = (a[2] & b[2]) | (a[2] ^ b[2]) & carry[1];

// Full adder for bit 3
assign sum[3] = a[3] ^ b[3] ^ carry[2];
assign carry[3] = (a[3] & b[3]) | (a[3] ^ b[3]) & carry[2];

// Full adder for bit 4
assign sum[4] = a[4] ^ b[4] ^ carry[3];
assign carry[4] = (a[4] & b[4]) | (a[4] ^ b[4]) & carry[3];

// Full adder for bit 5
assign sum[5] = a[5] ^ b[5] ^ carry[4];
assign carry[5] = (a[5] & b[5]) | (a[5] ^ b[5]) & carry[4];

// Full adder for bit 6
assign sum[6] = a[6] ^ b[6] ^ carry[5];
assign carry[6] = (a[6] & b[6]) | (a[6] ^ b[6]) & carry[5];

// Full adder for bit 7 (MSB)
assign sum[7] = a[7] ^ b[7] ^ carry[6];
assign cout = (a[7] & b[7]) | (a[7] ^ b[7]) & carry[6];

endmodule

