    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout);

    wire carry0, carry1, carry2, carry3, carry4, carry5, carry6;

    // Full adder for bit 0
    assign sum[0] = a[0] ^ b[0] ^ cin;
    assign carry0 = (a[0] & b[0]) | (a[0] & cin) | (b[0] & cin);

    // Full adder for bit 1
    assign sum[1] = a[1] ^ b[1] ^ carry0;
    assign carry1 = (a[1] & b[1]) | (a[1] & carry0) | (b[1] & carry0);

    // Full adder for bit 2
    assign sum[2] = a[2] ^ b[2] ^ carry1;
    assign carry2 = (a[2] & b[2]) | (a[2] & carry1) | (b[2] & carry1);

    // Full adder for bit 3
    assign sum[3] = a[3] ^ b[3] ^ carry2;
    assign carry3 = (a[3] & b[3]) | (a[3] & carry2) | (b[3] & carry2);

    // Full adder for bit 4
    assign sum[4] = a[4] ^ b[4] ^ carry3;
    assign carry4 = (a[4] & b[4]) | (a[4] & carry3) | (b[4] & carry3);

    // Full adder for bit 5
    assign sum[5] = a[5] ^ b[5] ^ carry4;
    assign carry5 = (a[5] & b[5]) | (a[5] & carry4) | (b[5] & carry4);

    // Full adder for bit 6
    assign sum[6] = a[6] ^ b[6] ^ carry5;
    assign carry6 = (a[6] & b[6]) | (a[6] & carry5) | (b[6] & carry5);

    // Full adder for bit 7
    assign sum[7] = a[7] ^ b[7] ^ carry6;
    assign cout = (a[7] & b[7]) | (a[7] & carry6) | (b[7] & carry6);
endmodule

