module cla_16bit(A, B, Cin, S, Cout);
    input [16:1] A;
    input [16:1] B;
    input Cin;
    output [16:1] S;
    output Cout;

    wire [16:1] P; // Propagate
    wire [16:1] G; // Generate
    wire [16:1] C; // Carry for each bit

    genvar i;

    // Compute Propagate and Generate signals
    generate
        for (i = 1; i <= 16; i = i + 1) begin : gen_pg
            assign P[i] = A[i] ^ B[i];
            assign G[i] = A[i] & B[i];
        end
    endgenerate

    // Carry logic
    // C[1] = Cin
    assign C[1] = Cin;

    // For each bit, compute carry using CLA logic
    // Since SystemVerilog 'generate' with loops can't be used for sequential dependencies without break,
    // we unroll manually for 16 bits

    // Bit 2
    assign C[2] = G[1] | (P[1] & C[1]);
    // Bit 3
    assign C[3] = G[2] | (P[2] & C[2]);
    // Bit 4
    assign C[4] = G[3] | (P[3] & C[3]);
    // Bit 5
    assign C[5] = G[4] | (P[4] & C[4]);
    // Bit 6
    assign C[6] = G[5] | (P[5] & C[5]);
    // Bit 7
    assign C[7] = G[6] | (P[6] & C[6]);
    // Bit 8
    assign C[8] = G[7] | (P[7] & C[7]);
    // Bit 9
    assign C[9] = G[8] | (P[8] & C[8]);
    // Bit 10
    assign C[10] = G[9] | (P[9] & C[9]);
    // Bit 11
    assign C[11] = G[10] | (P[10] & C[10]);
    // Bit 12
    assign C[12] = G[11] | (P[11] & C[11]);
    // Bit 13
    assign C[13] = G[12] | (P[12] & C[12]);
    // Bit 14
    assign C[14] = G[13] | (P[13] & C[13]);
    // Bit 15
    assign C[15] = G[14] | (P[14] & C[14]);
    // Bit 16
    assign C[16] = G[15] | (P[15] & C[15]);

    // Final carry out
    assign Cout = G[16] | (P[16] & C[16]);

    // Sum bits
    generate
        for (i = 1; i <= 16; i = i + 1) begin : sum_gen
            assign S[i] = P[i] ^ C[i];
