module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

// Internal signals
reg [DATA_WIDTH-1:0] adda_reg, addb_reg;
reg [DATA_WIDTH:0] sum_reg [0:1]; // To hold intermediate sums
reg carry_reg [0:1]; // Intermediate carry bits
reg [DATA_WIDTH-1:0] adda_pipe [0:1];
reg [DATA_WIDTH-1:0] addb_pipe [0:1];
reg carry_in, carry_out;
reg i_en_d1, i_en_d2; // Delayed enable signals

// Pipeline registers for enable signal
reg i_en_pipe [0:2];

integer i;

// Reset and input capture
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        adda_reg <= 0;
        addb_reg <= 0;
        for (i = 0; i < 2; i = i + 1) begin
            adda_pipe[i] <= 0;
            addb_pipe[i] <= 0;
            sum_reg[i] <= 0;
            carry_reg[i] <= 0;
        end
        o_en <= 0;
        for (i = 0; i < 3; i = i + 1) begin
            i_en_pipe[i] <= 0;
        end
    end else begin
        // Shift enable signals
        i_en_pipe[0] <= i_en;
        i_en_pipe[1] <= i_en_pipe[0];
        i_en_pipe[2] <= i_en_pipe[1];

        // Capture inputs when enable is high
        if (i_en) begin
            adda_reg <= adda;
            addb_reg <= addb;
        end

        // Pipeline stage 1: register inputs
        adda_pipe[0] <= adda_reg;
        addb_pipe[0] <= addb_reg;

        // Stage 2: perform addition with carry
        if (i_en_pipe[0]) begin
            {carry_out, sum_reg[0]} <= {1'b0, adda_pipe[0]} + {1'b0, addb_pipe[0]};
            carry_reg[0] <= carry_out;
        end else begin
            sum_reg[0] <= 0;
            carry_reg[0] <= 0;
        end

        // Pipeline stage 2: register sum and carry
        if (i_en_pipe[1]) begin
            sum_reg[1] <= sum_reg[0];
            carry_reg[1] <= carry_reg[0];
        end else begin
            sum_reg[1] <= 0;
            carry_reg[1] <= 0;
        end

        // Final stage: output result
        if (i_en_pipe[2]) begin
            result <= {carry_reg[1], sum_reg[1]};
            o_en <= 1;
        end else begin
            result <= 0;
            o_en <= 0;
        end
    end
end

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

// Internal signals
reg [DATA_WIDTH-1:0] adda_reg, addb_reg;
reg [DATA_WIDTH:0] sum_pipe [0: (DATA_WIDTH/16)]; // pipeline stages for sum
reg [DATA_WIDTH/16:0] carry_pipe [0: (DATA_WIDTH/16)]; // pipeline stages for carry
reg [DATA_WIDTH/16:0] carry_in_stage;
reg [DATA_WIDTH-1:0] adda_stage, addb_stage;
reg [DATA_WIDTH/16:0] sum_stage [0: (DATA_WIDTH/16)];
reg [DATA_WIDTH/16:0] carry_stage [0: (DATA_WIDTH/16)];
reg i_en_d; // delayed enable for pipeline control

// Initialize registers
integer i;
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        adda_reg <= 0;
        addb_reg <= 0;
        o_en <= 0;
        i_en_d <= 0;
        for (i = 0; i <= (DATA_WIDTH/16); i = i + 1) begin
            sum_pipe[i] <= 0;
            carry_pipe[i] <= 0;
            sum_stage[i] <= 0;
            carry_stage[i] <= 0;
        end
    end else begin
        // Latch inputs when i_en is high
        if (i_en) begin
            adda_reg <= adda;
            addb_reg <= addb;
        end
        i_en_d <= i_en;

        // Pipeline stage 0: initial sum and carry
        if (i_en) begin
            sum_pipe[0] <= {1'b0, adda} + {1'b0, addb};
            carry_pipe[0] <= ({1'b0, adda} & {1'b0, addb}) >> (DATA_WIDTH - STG_WIDTH);
        end else if (i_en_d) begin
            sum_pipe[0] <= sum_stage[0];
            carry_pipe[0] <= carry_stage[0];
        end

        // Generate subsequent pipeline stages
        for (i = 1; i <= (DATA_WIDTH/16); i = i + 1) begin
            // Compute sum for stage i
            sum_pipe[i] <= sum_stage[i-1] + { { ( (carry_stage[i-1] >> (i*STG_WIDTH - 1)) ) }, {1'b0} } << (i*STG_WIDTH);
            // Compute carry for stage i
            carry_pipe[i] <= (sum_stage[i-1] & ( { { (carry_stage[i-1] >> (i*STG_WIDTH - 1)) }, {1'b0} } << (i*STG_WIDTH) )) >> ( (i+1)*STG_WIDTH - 1);
        end

        // Register stage sums and carries
        for (i = 0; i <= (DATA_WIDTH/16); i = i + 1) begin
            if (i == 0) begin
                sum_stage[i] <= sum_pipe[i];
                carry_stage[i] <= carry_pipe[i];
            end else begin
                sum_stage[i] <= sum_pipe[i];
                carry_stage[i] <= carry_pipe[i];
            end
        end

        // Final output assignment
        if (i_en_d) begin
            result <= {carry_stage[(DATA_WIDTH/16)], sum_stage[(DATA_WIDTH/16)]};
            o_en <= 1'b1;
        end else begin
            o_en <= 1'b0;
        end
    end
end

assign result = {carry_stage[(DATA_WIDTH/16)], sum_stage[(DATA_WIDTH/16)]};

endmodule

