            stage_en[i] <= 1'b0;
        end
        o_en <= 1'b0;
    end else begin
        // Shift enable signals through pipeline stages
        stage_en[0] <= i_en;
        stage_en[1] <= stage_en[0];
        stage_en[2] <= stage_en[1];
        stage_en[3] <= stage_en[2];
        stage_en[4] <= stage_en[3];

        // Final output enable when last stage is valid
        o_en <= stage_en[4];
    end
end

// Register inputs when i_en is asserted
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        for (i = 0; i <= 4; i = i + 1) begin
            adda_reg[i] <= {DATA_WIDTH{1'b0}};
            addb_reg[i] <= {DATA_WIDTH{1'b0}};
        end
        sum_reg[0] <= 0;
        result_reg <= 0;
        carry_in <= 0;
    end else begin
        if (stage_en[0]) begin
            adda_reg[0] <= adda;
            addb_reg[0] <= addb;
            sum_reg[0] <= {1'b0, adda} + {1'b0, addb};
            carry_in <= 1'b0;
        end
        for (i = 1; i <= 4; i = i + 1) begin
            if (stage_en[i]) begin
                adda_reg[i] <= adda_reg[i-1];
                addb_reg[i] <= addb_reg[i-1];
                sum_reg[i] <= {1'b0, adda_reg[i-1]} + {1'b0, addb_reg[i-1]} + sum_reg[i-1][0]; // propagate carry
            end
        end
        // Final stage sum and carry
        if (stage_en[4]) begin
            result_reg <= sum_reg[4];
        end
    end
end

// Assign the final result
assign result = result_reg;

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

// Internal signals for pipeline stages
reg [DATA_WIDTH-1:0] adda_pipe [0:3];
reg [DATA_WIDTH-1:0] addb_pipe [0:3];
reg [DATA_WIDTH:0] sum_pipe [0:3]; // to hold sum and carry
reg [DATA_WIDTH:0] carry_pipe [0:3];

reg i_en_pipe [0:3];

// Initialize registers
integer i;
initial begin
    for (i = 0; i < 4; i = i + 1) begin
        adda_pipe[i] = 0;
        addb_pipe[i] = 0;
        sum_pipe[i] = 0;
        carry_pipe[i] = 0;
        i_en_pipe[i] = 0;
    end
    o_en = 0;
end

// Pipeline registers and addition operations
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Reset all registers
        for (i = 0; i < 4; i = i + 1) begin
            adda_pipe[i] <= 0;
            addb_pipe[i] <= 0;
            sum_pipe[i] <= 0;
            carry_pipe[i] <= 0;
            i_en_pipe[i] <= 0;
        end
        o_en <= 0;
    end else begin
        // Stage 0: latch inputs if enabled
        if (i_en) begin
            adda_pipe[0] <= adda;
            addb_pipe[0] <= addb;
            i_en_pipe[0] <= 1;
        end else begin
            // Hold previous values if not enabled
            adda_pipe[0] <= adda_pipe[0];
            addb_pipe[0] <= addb_pipe[0];
            i_en_pipe[0] <= 0;
        end

        // Subsequent stages
        for (i = 1; i < 4; i = i + 1) begin
            if (i_en_pipe[i-1]) begin
                adda_pipe[i] <= adda_pipe[i-1];
                addb_pipe[i] <= addb_pipe[i-1];
                i_en_pipe[i] <= 1;
            end else begin
                adda_pipe[i] <= adda_pipe[i];
                addb_pipe[i] <= addb_pipe[i];
                i_en_pipe[i] <= 0;
            end
        end

        // Perform addition in each stage
        // Stage 1
        if (i_en_pipe[0]) begin
            {carry_pipe[0], sum_pipe[0][DATA_WIDTH-1:0]} <= adda_pipe[0] + addb_pipe[0];
            sum_pipe[0][DATA_WIDTH] <= carry_pipe[0];
        end else begin
            sum_pipe[0] <= sum_pipe[0];
            carry_pipe[0] <= carry_pipe[0];
        end

        // Stage 2
        if (i_en_pipe[1]) begin
            {carry_pipe[1], sum_pipe[1][DATA_WIDTH-1:0]} <= sum_pipe[0][DATA_WIDTH-1:0] + 0 + carry_pipe[0];
            sum_pipe[1][DATA_WIDTH] <= carry_pipe[1];
        end else begin
            sum_pipe[1] <= sum_pipe[1];
            carry_pipe[1] <= carry_pipe[1];
        end

        // Stage 3
        if (i_en_pipe[2]) begin
            {carry_pipe[2], sum_pipe[2][DATA_WIDTH-1:0]} <= sum_pipe[1][DATA_WIDTH-1:0] + 0 + carry_pipe[1];
            sum_pipe[2][DATA_WIDTH] <= carry_pipe[2];
        end else begin
            sum_pipe[2] <= sum_pipe[2];
            carry_pipe[2] <= carry_pipe[2];
        end

        // Final stage: assign result and o_en
        if (i_en_pipe[3]) begin
            result <= sum_pipe[2];
            o_en <= 1;
        end else begin
            result <= result;
            o_en <= 0;
        end
    end
end

endmodule

module asyn_fifo#(
	parameter WIDTH = 8,
	parameter DEPTH = 16
)(
	input wclk, 
	input rclk,   
	input wrstn,
	input rrstn,
	input winc,
	input rinc,
	input [WIDTH-1:0] wdata,

	output wire wfull,
	output wire rempty,
	output wire [WIDTH-1:0] rdata
);

parameter ADDR_WIDTH = $clog2(DEPTH);

// Internal signals
reg [ADDR_WIDTH-1:0] waddr_bin, raddr_bin;
wire [ADDR_WIDTH-1:0] waddr_bin_next, raddr_bin_next;

wire [ADDR_WIDTH-1:0] waddr_sync_in_rclk, raddr_sync_in_wclk;
reg [ADDR_WIDTH-1:0] waddr_bin_sync1, waddr_bin_sync2;
reg [ADDR_WIDTH-1:0] raddr_bin_sync1, raddr_bin_sync2;

wire [ADDR_WIDTH-1:0] waddr_gray, raddr_gray;
wire [ADDR_WIDTH-1:0] waddr_gray_sync, raddr_gray_sync;

wire [ADDR_WIDTH-1:0] waddr_gray_next, raddr_gray_next;

reg [WIDTH-1:0] mem [0:DEPTH-1];

wire winc_en, rinc_en;
wire [WIDTH-1:0] rdata_reg;

wire rempty_int, wfull_int;

// Convert binary to Gray code
function [ADDR_WIDTH-1:0] bin2gray;
	input [ADDR_WIDTH-1:0] bin;
	begin
		bin2gray = (bin >> 1) ^ bin;
	end
endfunction

// Convert Gray to binary
function [ADDR_WIDTH-1:0] gray2bin;
	input [ADDR_WIDTH-1:0] gray;
	reg [ADDR_WIDTH-1:0] bin;
	integer i;
	begin
		bin[ADDR_WIDTH-1] = gray[ADDR_WIDTH-1];
		for (i = ADDR_WIDTH-2; i >= 0; i = i - 1)
			bin[i] = bin[i+1] ^ gray[i];
		gray2bin = bin;
	end
endfunction

// Write Pointer Logic
always @(posedge wclk or negedge wrstn) begin
	if (!wrstn)
		waddr_bin <= 0;
	else if (winc && !wfull)
		waddr_bin <= waddr_bin_next;
end

assign waddr_bin_next = waddr_bin + (winc && !wfull ? 1 : 0);
assign waddr_gray = bin2gray(waddr_bin);

// Read Pointer Logic
always @(posedge rclk or negedge rrstn) begin
	if (!rrstn)
		raddr_bin <= 0;
	else if (rinc && !rempty)
		raddr_bin <= raddr_bin_next;
end

assign raddr_bin_next = raddr_bin + (rinc && !rempty ? 1 : 0);
assign raddr_gray = bin2gray(raddr_bin);

// Write Pointer Synchronization into read clock domain
always @(posedge rclk or negedge rrstn) begin
	if (!rrstn) begin
		waddr_bin_sync1 <= 0;
		waddr_bin_sync2 <= 0;
	end else begin
		waddr_bin_sync1 <= waddr_bin;
		waddr_bin_sync2 <= waddr_bin_sync1;
	end
end

assign waddr_sync_in_rclk = waddr_bin_sync2;

// Read Pointer Synchronization into write clock domain
always @(posedge wclk or negedge wrstn) begin
	if (!wrstn) begin
		raddr_bin_sync1 <= 0;
		raddr_bin_sync2 <= 0;
	end else begin
		raddr_bin_sync1 <= raddr_bin;
		raddr_bin_sync2 <= raddr_bin_sync1;
	end
end

assign raddr_sync_in_wclk = raddr_bin_sync2;

// Convert synchronized pointers to Gray
assign waddr_gray_sync = bin2gray(waddr_sync_in_rclk);
assign raddr_gray_sync = bin2gray(raddr_sync_in_wclk);

// Detect empty: when write pointer == read pointer
assign rempty_int = (waddr_gray == raddr_gray);
assign rempty = rempty_int;

// Detect full: when write pointer is one ahead of read pointer in Gray code
wire [ADDR_WIDTH-1:0] wptr_plus = bin2gray(waddr_bin + (winc && !wfull ? 1 : 0));
wire [ADDR_WIDTH-1:0] rptr_gray = raddr_gray_sync;
assign wfull_int = (waddr_gray == rptr_gray) && (waddr_bin_next != gray2bin(raddr_gray_sync));
assign wfull = wfull_int;

// Write enable
assign wfull = wfull_int;
assign winc_en = winc && !wfull;

// Read enable
assign rempty = rempty_int;
assign rinc_en = rinc && !rempty;

// RAM Write
always @(posedge wclk) begin
	if (winc_en)
		mem[waddr_bin] <= wdata;
end

// RAM Read
assign rdata = mem[raddr_bin];

// Output read data register (optional, for timing)
reg [WIDTH-1:0] rdata_reg;
always @(posedge rclk) begin
	rdata_reg <= rdata;
end
assign rdata = rdata_reg;

endmodule

module asyn_fifo#(
    parameter WIDTH = 8,
    parameter DEPTH = 16
)(
