    input [WIDTH-1:0]       wdata     ,
    output wire             wfull     ,
    output wire             rempty    ,
    output wire [WIDTH-1:0] rdata
);

localparam ADDR_WIDTH = $clog2(DEPTH);

// Internal signals
reg [ADDR_WIDTH-1:0] waddr_bin, raddr_bin;
reg [ADDR_WIDTH-1:0] waddr_bin_next, raddr_bin_next;
wire [ADDR_WIDTH-1:0] waddr, raddr;
wire [ADDR_WIDTH-1:0] waddr_sync, raddr_sync;

// Gray code conversion functions
function [ADDR_WIDTH-1:0] bin2gray(input [ADDR_WIDTH-1:0] bin);
    integer i;
    begin
        bin2gray[ADDR_WIDTH-1] = bin[ADDR_WIDTH-1];
        for (i=ADDR_WIDTH-2; i>=0; i=i-1)
            bin2gray[i] = bin[i+1] ^ bin[i];
    end
endfunction

function [ADDR_WIDTH-1:0] gray2bin(input [ADDR_WIDTH-1:0] gray);
    integer i;
    begin
        gray2bin[ADDR_WIDTH-1] = gray[ADDR_WIDTH-1];
        for (i=ADDR_WIDTH-2; i>=0; i=i-1)
            gray2bin[i] = gray2bin[i+1] ^ gray[i];
    end
endfunction

// Write Pointer (binary and Gray)
always @(posedge wclk or negedge wrstn) begin
    if (!wrstn)
        waddr_bin <= 0;
    else if (winc && !wfull)
        waddr_bin <= waddr_bin_next;
end

assign waddr = waddr_bin;

// Convert write binary pointer to Gray
wire [ADDR_WIDTH-1:0] wptr_gray = bin2gray(waddr_bin);

// Read Pointer (binary and Gray)
always @(posedge rclk or negedge rrstn) begin
    if (!rrstn)
        raddr_bin <= 0;
    else if (rinc && !rempty)
        raddr_bin <= raddr_bin_next;
end

assign raddr = raddr_bin;

// Convert read binary pointer to Gray
wire [ADDR_WIDTH-1:0] rptr_gray = bin2gray(raddr_bin);

// Synchronize write pointer Gray into read clock domain
reg [ADDR_WIDTH-1:0] wptr_gray_sync1, wptr_gray_sync2;
always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        wptr_gray_sync1 <= 0;
        wptr_gray_sync2 <= 0;
    end else begin
        wptr_gray_sync1 <= wptr_gray;
        wptr_gray_sync2 <= wptr_gray_sync1;
    end
end

// Synchronize read pointer Gray into write clock domain
reg [ADDR_WIDTH-1:0] rptr_gray_sync1, rptr_gray_sync2;
always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        rptr_gray_sync1 <= 0;
        rptr_gray_sync2 <= 0;
    end else begin
        rptr_gray_sync1 <= rptr_gray;
        rptr_gray_sync2 <= rptr_gray_sync1;
    end
end

// Convert synchronized Gray pointers to binary
wire [ADDR_WIDTH-1:0] wptr_gray_sync = wptr_gray_sync2;
wire [ADDR_WIDTH-1:0] rptr_gray_sync = rptr_gray_sync2;

wire [ADDR_WIDTH-1:0] wptr_bin_sync = gray2bin(wptr_gray_sync);
wire [ADDR_WIDTH-1:0] rptr_bin_sync = gray2bin(rptr_gray_sync);

// Pointer next values
always @(*) begin
    waddr_bin_next = waddr_bin;
    if (winc && !wfull)
        waddr_bin_next = waddr_bin + 1;
end

always @(*) begin
    raddr_bin_next = raddr_bin;
    if (rinc && !rempty)
        raddr_bin_next = raddr_bin + 1;
end

// Empty condition: when write and read pointers are equal
assign rempty = (wptr_gray == rptr_gray_sync);

// Full condition: when next write pointer equals read pointer with MSB inverted
wire [ADDR_WIDTH-1:0] wptr_next_gray = bin2gray(waddr_bin_next);
wire full_flag = (wptr_next_gray == {~rptr_gray_sync[ADDR_WIDTH-1], rptr_gray_sync[ADDR_WIDTH-2:0]});
assign wfull = full_flag;

// Dual-port RAM
reg [WIDTH-1:0] ram [0:DEPTH-1];

always @(posedge wclk) begin
    if (winc && !wfull)
        ram[waddr] <= wdata;
end

assign rdata = ram[raddr];

// Instantiate dual-port RAM (using behavioral style here)
// No separate module needed for this example

endmodule

module asyn_fifo#(
	parameter WIDTH = 8,
	parameter DEPTH = 16
)(
	input wclk, 
	input rclk,   
	input wrstn,
	input rrstn,
	input winc,
	input rinc,
	input [WIDTH-1:0] wdata,
	output wire wfull,
	output wire rempty,
	output wire [WIDTH-1:0] rdata
);

localparam ADDR_WIDTH = $clog2(DEPTH);

// ---------------------------
// Dual-Port RAM Module
// ---------------------------
reg [WIDTH-1:0] mem [0:DEPTH-1];

wire [ADDR_WIDTH-1:0] waddr;
wire [ADDR_WIDTH-1:0] raddr;
reg [WIDTH-1:0] rdata_reg;

always @(posedge wclk) begin
	if (winc && !wfull) begin
		mem[waddr] <= wdata;
	end
end

always @(posedge rclk) begin
	rdata_reg <= mem[raddr];
end

assign rdata = rdata_reg;

// ---------------------------
// Write Pointer Logic
// ---------------------------
reg [ADDR_WIDTH:0] wptr_bin; // binary write pointer
reg [ADDR_WIDTH:0] wptr_bin_next;
reg [ADDR_WIDTH:0] wptr_bin_sync1, wptr_bin_sync2; // synchronized write pointer in read domain

wire [ADDR_WIDTH-1:0] waddr_bin = wptr_bin[ADDR_WIDTH-1:0];
wire [ADDR_WIDTH-1:0] waddr_gray;
wire [ADDR_WIDTH-1:0] wptr_gray;

function [ADDR_WIDTH-1:0] bin2gray;
	input [ADDR_WIDTH-1:0] bin;
	begin
		bin2gray = (bin >> 1) ^ bin;
	end
endfunction

// Increment write pointer
always @(posedge wclk or negedge wrstn) begin
	if (!wrstn)
		wptr_bin <= 0;
	else if (winc && !wfull)
		wptr_bin <= wptr_bin_next;
end

always @(*) begin
	wptr_bin_next = wptr_bin + 1;
end

assign wptr_gray = bin2gray(wptr_bin);
assign waddr = waddr_bin;

// ---------------------------
// Read Pointer Logic
// ---------------------------
reg [ADDR_WIDTH:0] rptr_bin; // binary read pointer
reg [ADDR_WIDTH:0] rptr_bin_next;
reg [ADDR_WIDTH:0] rptr_bin_sync1, rptr_bin_sync2; // synchronized read pointer in write domain

wire [ADDR_WIDTH-1:0] raddr_bin = rptr_bin[ADDR_WIDTH-1:0];
wire [ADDR_WIDTH-1:0] raddr_gray;
wire [ADDR_WIDTH-1:0] rptr_gray;

always @(posedge rclk or negedge rrstn) begin
	if (!rrstn)
		rptr_bin <= 0;
	else if (rinc && !rempty)
		rptr_bin <= rptr_bin_next;
end

always @(*) begin
	rptr_bin_next = rptr_bin + 1;
end

assign rptr_gray = bin2gray(rptr_bin);
assign raddr = raddr_bin;

// ---------------------------
// Synchronize write pointer into read domain
// ---------------------------
reg [ADDR_WIDTH:0] wptr_gray_sync1, wptr_gray_sync2;

always @(posedge rclk or negedge rrstn) begin
	if (!rrstn) begin
		wptr_gray_sync1 <= 0;
		wptr_gray_sync2 <= 0;
	end else begin
		wptr_gray_sync1 <= wptr_gray;
		wptr_gray_sync2 <= wptr_gray_sync1;
	end
end

// Convert synchronized write pointer Gray code to binary
function [ADDR_WIDTH:0] gray2bin;
	input [ADDR_WIDTH:0] gray;
	begin
		gray2bin = gray[ADDR_WIDTH:0];
		integer i;
		for (i = ADDR_WIDTH - 1; i >= 0; i = i - 1)
			gray2bin[i] = gray[i+1] ^ gray2bin[i+1];
	end
endfunction

wire [ADDR_WIDTH:0] wptr_bin_sync = gray2bin(wptr_gray_sync2);

// ---------------------------
// Synchronize read pointer into write domain
// ---------------------------
reg [ADDR_WIDTH:0] rptr_gray_sync1, rptr_gray_sync2;

always @(posedge wclk or negedge wrstn) begin
	if (!wrstn) begin
		rptr_gray_sync1 <= 0;
		rptr_gray_sync2 <= 0;
	end else begin
		rptr_gray_sync1 <= rptr_gray;
		rptr_gray_sync2 <= rptr_gray_sync1;
	end
end

wire [ADDR_WIDTH:0] rptr_bin_sync = gray2bin(rptr_gray_sync2);

// ---------------------------
// Empty and Full Flags
// ---------------------------
assign rempty = (wptr_gray == rptr_gray);
assign wfull = ( (wptr_gray[ADDR_WIDTH] != rptr_gray_sync2[ADDR_WIDTH]) && (wptr_gray[ADDR_WIDTH-1:0] == rptr_gray_sync2[ADDR_WIDTH-1:0]) );

// ---------------------------
// Address Assignments
// ---------------------------
