	if (~rrstn) begin
		raddr_bin_sync1 <= 0;
		raddr_bin_sync2 <= 0;
	end else begin
		raddr_bin_sync1 <= waddr_gray_sync;
		raddr_bin_sync2 <= raddr_bin_sync1;
	end
end

// Synchronize Gray code pointers
reg [ADDR_WIDTH-1:0] waddr_gray_sync;
reg [ADDR_WIDTH-1:0] raddr_gray_sync;

always @(posedge wclk or negedge wrstn) begin
	if (~wrstn) begin
		waddr_gray_sync <= 0;
	end else begin
