// Convert synchronized Gray codes back to binary
wire [ADDR_WIDTH-1:0] raddr_bin_sync = gray2bin(waddr_gray_sync);
wire [ADDR_WIDTH-1:0] waddr_bin_sync = gray2bin(raddr_gray_sync);

// Update write address
wire winc_active = winc && !wfull;
wire rinc_active = rinc && !rempty;

