		raddr_bin <= 0;
	end else if (rinc_active) begin
		raddr_bin <= raddr_bin + 1;
	end
end

// Generate full and empty signals
assign wfull = (bin2gray(waddr_bin + 1) == raddr_gray_sync);
assign rempty = (waddr_gray == raddr_gray_sync);

// Write data into RAM
always @(posedge wclk) begin
	if (winc_active) begin
		mem[waddr] <= wdata;
	end
end

// Output the current read data
