module asyn_fifo#(
    parameter WIDTH = 8,
    parameter DEPTH = 16
)(
    input                   wclk    , 
    input                   rclk    ,   
    input                   wrstn   ,
    input                   rrstn   ,
    input                   winc    ,
    input                   rinc    ,
    input   [WIDTH-1:0]     wdata   ,

    output wire             wfull   ,
    output wire             rempty  ,
    output wire [WIDTH-1:0]  rdata
);

localparam ADDR_WIDTH = $clog2(DEPTH);

// Internal signals
reg [ADDR_WIDTH-1:0] waddr_bin, raddr_bin;
reg [ADDR_WIDTH-1:0] waddr_bin_next, raddr_bin_next;
reg [ADDR_WIDTH-1:0] waddr_gray, raddr_gray;
reg [ADDR_WIDTH-1:0] waddr_gray_sync1, waddr_gray_sync2;
reg [ADDR_WIDTH-1:0] raddr_gray_sync1, raddr_gray_sync2;

wire [ADDR_WIDTH-1:0] waddr_bin_next_wire, raddr_bin_next_wire;
wire [ADDR_WIDTH-1:0] waddr_gray_next, raddr_gray_next;
wire [ADDR_WIDTH-1:0] waddr_gray_sync, raddr_gray_sync;

// Dual-port RAM
reg [WIDTH-1:0] mem [0:DEPTH-1];
wire [ADDR_WIDTH-1:0] mem_waddr, mem_raddr;
wire [WIDTH-1:0] q_rdata;

// Synchronize write pointer Gray into read domain
always @(posedge rclk or negedge rrstn) begin
    if (~rrstn) begin
        waddr_gray_sync1 <= 0;
        waddr_gray_sync2 <= 0;
    end else begin
        waddr_gray_sync1 <= waddr_gray;
        waddr_gray_sync2 <= waddr_gray_sync1;
    end
end

// Synchronize read pointer Gray into write domain
always @(posedge wclk or negedge wrstn) begin
    if (~wrstn) begin
        raddr_gray_sync1 <= 0;
        raddr_gray_sync2 <= 0;
    end else begin
        raddr_gray_sync1 <= raddr_gray;
        raddr_gray_sync2 <= raddr_gray_sync1;
    end
end

// Binary to Gray code conversion
function [ADDR_WIDTH-1:0] bin2gray(input [ADDR_WIDTH-1:0] bin);
    begin
        bin2gray = (bin >> 1) ^ bin;
    end
endfunction

// Gray to Binary conversion
function [ADDR_WIDTH-1:0] gray2bin(input [ADDR_WIDTH-1:0] gray);
    integer i;
    begin
        gray2bin[ADDR_WIDTH-1] = gray[ADDR_WIDTH-1];
        for (i = ADDR_WIDTH-2; i >= 0; i = i -1) begin
            gray2bin[i] = gray2bin[i+1] ^ gray[i];
        end
    end
endfunction

// Update write pointer
always @(posedge wclk or negedge wrstn) begin
    if (~wrstn) begin
        waddr_bin <= 0;
        waddr_gray <= 0;
    end else begin
        if (winc && ~wfull) begin
            waddr_bin <= waddr_bin_next_wire;
            waddr_gray <= waddr_gray_next;
        end
    end
end

// Update read pointer
always @(posedge rclk or negedge rrstn) begin
    if (~rrstn) begin
        raddr_bin <= 0;
        raddr_gray <= 0;
    end else begin
        if (rinc && ~rempty) begin
            raddr_bin <= raddr_bin_next_wire;
            raddr_gray <= raddr_gray_next;
        end
    end
end

// Next binary address calculation
assign waddr_bin_next_wire = waddr_bin + (winc && ~wfull ? 1 : 0);
assign raddr_bin_next_wire = raddr_bin + (rinc && ~rempty ? 1 : 0);

// Gray code next value
assign waddr_gray_next = bin2gray(waddr_bin_next_wire);
assign raddr_gray_next = bin2gray(raddr_bin_next_wire);

// Synchronize pointers
assign waddr_gray_sync = waddr_gray_sync2;
assign raddr_gray_sync = raddr_gray_sync2;

// Convert synchronized Gray to binary
wire [ADDR_WIDTH-1:0] rptr_bin_in, wptr_bin_in;
assign rptr_bin_in = gray2bin(waddr_gray_sync);
assign wptr_bin_in = gray2bin(raddr_gray_sync);

// Assign addresses for RAM
assign mem_waddr = waddr_bin;
assign mem_raddr = raddr_bin;

// Read data
assign rdata = q_rdata;

// Write to RAM
always @(posedge wclk) begin
    if (winc && ~wfull) begin
        mem[mem_waddr] <= wdata;
    end
end

// Read from RAM
assign q_rdata = mem[mem_raddr];

// Full and Empty flags
// Full condition: when next write address equals read address Gray code shifted by 1
assign wfull = (waddr_gray == ((raddr_gray ^ (1 << (ADDR_WIDTH-1)))));

// Empty condition: when write pointer equals read pointer
assign rempty = (waddr_gray == raddr_gray);

endmodule

