    input CLK_in, RST;
    output reg CLK_50, CLK_10, CLK_1;

    reg [0:0] cnt_50;      // Counter for dividing by 2 (for 50MHz)
    reg [2:0] cnt_10;      // Counter for dividing by 10 (for 10MHz)
    reg [6:0] cnt_100;     // Counter for dividing by 100 (for 1MHz)

    always @(posedge CLK_in or posedge RST) begin
        if (RST) begin
            CLK_50 <= 0;
            CLK_10 <= 0;
            CLK_1 <= 0;
            cnt_50 <= 0;
            cnt_10 <= 0;
            cnt_100 <= 0;
        end else begin
            // Divide by 2 for CLK_50
            CLK_50 <= ~CLK_50;

            // Counter for CLK_10 (divide by 10)
            if (cnt_10 == 4) begin
                CLK_10 <= ~CLK_10;
                cnt_10 <= 0;
            end else begin
                cnt_10 <= cnt_10 + 1;
            end

            // Counter for CLK_1 (divide by 100)
            if (cnt_100 == 49) begin
                CLK_1 <= ~CLK_1;
                cnt_100 <= 0;
            end else begin
                cnt_100 <= cnt_100 + 1;
            end
        end
    end
endmodule

