output reg CLK_50,CLK_10,CLK_1;

reg [2:0] cnt_10;   // Counter for dividing by 10 (counts 0 to 4)
reg [6:0] cnt_100;  // Counter for dividing by 100 (counts 0 to 49)

// Toggle CLK_50 every positive edge of CLK_in
always @(posedge CLK_in or posedge RST) begin
    if (RST) begin
        CLK_50 <= 0;
    end else begin
        CLK_50 <= ~CLK_50;
    end
end

// Counter for CLK_10 (divide by 10)
always @(posedge CLK_in or posedge RST) begin
    if (RST) begin
        cnt_10 <= 0;
        CLK_10 <= 0;
    end else begin
        if (cnt_10 == 4) begin
            cnt_10 <= 0;
            CLK_10 <= ~CLK_10;
        end else begin
            cnt_10 <= cnt_10 + 1;
        end
    end
end

// Counter for CLK_1 (divide by 100)
always @(posedge CLK_in or posedge RST) begin
    if (RST) begin
        cnt_100 <= 0;
        CLK_1 <= 0;
    end else begin
        if (cnt_100 == 49) begin
            cnt_100 <= 0;
            CLK_1 <= ~CLK_1;
        end else begin
            cnt_100 <= cnt_100 + 1;
        end
    end
end

endmodule

