module fsm(IN, MATCH, CLK, RST);
  input IN, CLK, RST;
  output reg MATCH;

  // State encoding
  parameter S0 = 3'b000;
  parameter S1 = 3'b001;
  parameter S2 = 3'b010;
  parameter S3 = 3'b011;
  parameter S4 = 3'b100;
  parameter S5 = 3'b101;

  reg [2:0] state, next_state;

  always @(posedge CLK or posedge RST) begin
    if (RST) begin
      state <= S0;
    end else begin
      state <= next_state;
    end
  end

  always @(*) begin
    case (state)
      S0: begin
        if (IN)
          next_state = S1;
        else
          next_state = S0;
      end
      S1: begin
        if (IN)
          next_state = S1; // stay in S1 if another '1' (sequence overlapping)
        else
          next_state = S2;
      end
      S2: begin
        if (IN)
          next_state = S3;
        else
          next_state = S0;
      end
      S3: begin
        if (IN)
          next_state = S4;
        else
          next_state = S2;
      end
      S4: begin
        if (IN)
          next_state = S5;
        else
          next_state = S2;
      end
      S5: begin
        if (IN)
          next_state = S1; // detect overlapping sequence
        else
          next_state = S2;
      end
      default: next_state = S0;
    endcase
  end

  always @(*) begin
    if (state == S5)
      MATCH = 1;
    else
      MATCH = 0;
  end
endmodule

