        if (IN)
          next_state = S1;
        else
          next_state = S0;
      end
      S1: begin
        if (IN)
          next_state = S1; // stay if consecutive '1'
        else
          next_state = S2; // move to '10'
      end
      S2: begin
        if (IN)
          next_state = S1; // restart detection at '1'
        else
          next_state = S3; // move to '100'
      end
      S3: begin
        if (IN)
          next_state = S4; // move to '1001'
        else
          next_state = S0; // reset if '0'
