          next_state = S2; // move to '10' to detect overlapping
      end
      S5: begin
        if (IN)
          next_state = S1; // overlapping detection, start at '1'
        else
          next_state = S2; // move to '10'
      end
      default: next_state = S0;
    endcase
  end

  // Output logic
  always @(*) begin
    if (state == S5)
      MATCH = 1;
    else
