reg [2:0] state, next_state;

// State encoding
parameter S0 = 3'b000,
          S1 = 3'b001,
          S2 = 3'b010,
          S3 = 3'b011,
          S4 = 3'b100,
          S5 = 3'b101;

// Sequential logic for state transition
always @(posedge CLK or posedge RST) begin
    if (RST)
        state <= S0;
    else
        state <= next_state;
end

// Combinational logic for next state
always @(*) begin
    case (state)
        S0: begin
            if (IN)
                next_state = S1;
            else
                next_state = S0;
        end
        S1: begin
            if (IN)
                next_state = S1;
            else
                next_state = S2;
        end
        S2: begin
            if (IN)
                next_state = S1;
            else
                next_state = S3;
        end
        S3: begin
            if (IN)
                next_state = S4;
            else
                next_state = S0;
        end
        S4: begin
            if (IN)
                next_state = S5;
            else
                next_state = S2;
        end
        S5: begin
            if (IN)
                next_state = S1;
            else
                next_state = S2;
        end
        default: next_state = S0;
    endcase
end

// Output logic
always @(*) begin
    if (state == S5)
        MATCH = 1;
    else
        MATCH = 0;
end
endmodule

module fsm(IN, MATCH, CLK, RST);
    input IN, CLK, RST;
    output reg MATCH;

    // State encoding
    parameter S0 = 3'b000;
    parameter S1 = 3'b001;
    parameter S2 = 3'b010;
    parameter S3 = 3'b011;
    parameter S4 = 3'b100;
    parameter S5 = 3'b101;

    reg [2:0] state, next_state;

    // State register
    always @(posedge CLK or posedge RST) begin
        if (RST)
            state <= S0;
        else
            state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (state)
            S0: begin
                if (IN)
                    next_state = S1;
                else
                    next_state = S0;
            end
            S1: begin
                if (IN)
                    next_state = S1; // stay in S1 if consecutive '1's
                else
                    next_state = S2;
            end
            S2: begin
                if (IN)
                    next_state = S1; // restart detection if '1'
                else
                    next_state = S3;
            end
            S3: begin
                if (IN)
                    next_state = S4;
                else
                    next_state = S0;
            end
            S4: begin
                if (IN)
                    next_state = S5;
                else
                    next_state = S2;
            end
            S5: begin
                if (IN)
                    next_state = S1; // continue detection for overlapping sequences
                else
                    next_state = S2;
            end
            default: next_state = S0;
        endcase
    end

    // Output logic
    always @(*) begin
        if (state == S5)
            MATCH = 1;
        else
            MATCH = 0;
    end
endmodule

module JC_counter(
   input                clk,
   input                rst_n,
   output reg [63:0]    Q
);

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        Q <= 64'b0;
    end else begin
        // Shift right by 1
        Q <= {Q[62:0], 1'b0};
        // Insert bit at MSB based on Q[0]
        if (Q[0] == 1'b0) begin
            Q[63] <= 1'b1;
        end else begin
            Q[63] <= 1'b0;
        end
    end
end

endmodule

