    input [15:0] bin,
    output [31:0] yout,
    output done
);

reg [15:0] areg;
reg [15:0] breg;
reg [31:0] yout_r;
reg [4:0] i; // count from 0 to 16, so 5 bits
reg done_r;

assign yout = yout_r;
assign done = done_r;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        areg <= 16'b0;
        breg <= 16'b0;
        yout_r <= 32'b0;
        i <= 5'b0;
        done_r <= 1'b0;
    end else begin
        if (start) begin
            // Load inputs into registers
            areg <= ain;
            breg <= bin;
            yout_r <= 32'b0;
            i <= 5'b0;
            done_r <= 1'b0;
        end else if (i < 17) begin
            // Perform multiplication steps
            if (i > 0) begin
                // Check if the (i-1)th bit of areg is 1
                if (areg[i-1]) begin
                    yout_r <= yout_r + (breg << (i-1));
                end
            end
            i <= i + 1;
            // Set done flag when i reaches 16
            if (i == 15) begin
                done_r <= 1'b1;
            end else if (i == 16) begin
                // Reset done flag after operation completes
                done_r <= 1'b0;
            end
        end
    end
