module multi_booth_8bit (p, rdy, clk, reset, a, b);
    input clk, reset;
    input [7:0] a, b;
    output [15:0] p;
    output rdy;

    reg [15:0] multiplicand;   // Holds sign-extended 'a'
    reg [15:0] multiplier;     // Holds sign-extended 'b'
    reg [15:0] product;        // Accumulates result
    reg [4:0] ctr;             // Cycle counter (up to 16)
    reg rdy_reg;               // Ready signal

    wire [1:0] booth_code;     // For Booth encoding
    reg [15:0] multiplicand_shifted; // Shifted multiplicand

    assign p = product;
    assign rdy = rdy_reg;

    // Booth encoding based on current bits of multiplier
    // For simplicity, we consider bits [ctr:ctr-1], but since we process in sequence,
    // we can interpret bits accordingly. Here, for 8-bit radix-4, process 4 bits at a time.
    // But since the problem states not to use SystemVerilog, and to keep it simple,
    // we'll process bits sequentially, shifting the multiplier and examining bits.

    // To implement Radix-4 Booth, we need to look at pairs of bits.
    // For simplicity, we'll process the multiplier in bits, two at a time, starting from LSB.

    // But since the problem states not to use break statements, and for simplicity,
    // we'll implement a straightforward sequential Booth multiplication.

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Initialize all registers
            multiplicand <= { {8{a[7]} } }, a }; // Sign-extend to 16 bits
            multiplier <= { {8{b[7]} } }, b };   // Sign-extend to 16 bits
            product <= 0;
            ctr <= 0;
            rdy_reg <= 0;
            multiplicand_shifted <= {16{1'b0}};
        end else begin
            if (ctr == 0) begin
                // Start of multiplication
                product <= 0;
                ctr <= 0;
                rdy_reg <= 0;
                multiplicand <= { {8{a[7]} } }, a }; // Sign-extend
                multiplier <= { {8{b[7]} } }, b };   // Sign-extend
                multiplicand_shifted <= {16{1'b0}};
            end else if (ctr <= 16) begin
                // Booth algorithm iteration
                // Examine last 2 bits of multiplier for Booth encoding
                // For simplicity, we process bits starting from LSB
                // Extract bits for current operation
                // Since we are not using SystemVerilog, and to keep it simple,
                // process sequentially with shifting

                // Booth encoding:
                // - If bits [0,1] == 01 => add multiplicand
                // - If bits [0,1] == 10 => subtract multiplicand
                // - Else do nothing

                // For this implementation, we process 2 bits at a time
                // and shift multiplier right each cycle

                // Extract bits
                reg [1:0] booth_bits;
                booth_bits = {multiplier[1], multiplier[0]};

                // Decide action based on booth bits
                case (booth_bits)
                    2'b01: product <= product + (multiplicand);
                    2'b10: product <= product - (multiplicand);
                    default: ; // Do nothing
                endcase

                // Shift multiplier right by 2 bits
                multiplier <= {multiplier[15], multiplier[15:2]};
                // Shift multiplicand left by 2 bits for next step
                multiplicand <= multiplicand <<< 2;

                // Increment counter
                ctr <= ctr + 1;

                // When 16 cycles complete
                if (ctr == 15) begin
                    rdy_reg <= 1;
                end
            end
        end
    end
endmodule

