                        product <= product;
                    end
                endcase

                // Shift the multiplier right by 1 for next cycle
                multiplier <= {multiplier[15], multiplier[15:1]};
                // Shift the multiplicand left by 1 for next cycle
                multiplicand <= multiplicand << 1;
                // Update previous bit
                prev_bit <= current_bit;

                // Increment counter
                ctr <= ctr + 1;
            end else if (ctr == 16) begin
                // Final cycle completed
                rdy_reg <= 1'b1;
                ctr <= ctr + 1; // stay at 17 to hold rdy high
            end
        end
    end
endmodule

module multi_pipe_4bit#(
	parameter size = 4
)(
	input 						clk 		,   
	input 						rst_n		,
	input	[size-1:0]			mul_a		,
	input	[size-1:0]			mul_b		,

 	output	reg	[size*2-1:0]	mul_out		
);

parameter N = 2 * size;

// Internal signals
reg [size-1:0] mul_a_ext;
reg [size-1:0] mul_b_ext;

reg [size-1:0] partial_products [size-1:0]; // Partial products
reg [size+size-1:0] sum_stage1 [size-1:0];   // First level sum pipeline
reg [size+size-1:0] sum_stage2;              // Final sum register

// Reset and input extension
always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		mul_out <= 0;
	end else begin
		mul_out <= sum_stage2;
	end
end

// Generate partial products
genvar i;
generate
	for (i = 0; i < size; i = i + 1) begin : partial_product_gen
		always @(posedge clk or negedge rst_n) begin
			if (!rst_n) begin
				partial_products[i] <= 0;
			end else begin
				if (mul_b[i])
					partial_products[i] <= mul_a << i;
				else
					partial_products[i] <= 0;
			end
		end
	end
endgenerate

// First level addition: sum partial products pairwise
// Using pipeline registers for stage 1
reg [size+size-1:0] sum_reg1 [size/2-1:0]; // For even size, size/2 sums
reg [size+size-1:0] sum_reg2 [size/2-1:0]; // Next pipeline stage

generate
	if (size >= 2) begin
		for (i = 0; i < size/2; i = i + 1) begin : stage1_add
			always @(posedge clk or negedge rst_n) begin
				if (!rst_n) begin
					sum_reg1[i] <= 0;
				end else begin
					sum_reg1[i] <= partial_products[2*i] + partial_products[2*i + 1];
				end
			end
		end
	end
endgenerate

// Handle odd size case if size is odd
// For size=4, no need; but for generality, handle it
generate
	if (size % 2 == 1) begin
		reg [size+size-1:0] last_partial;
		always @(posedge clk or negedge rst_n) begin
			if (!rst_n) begin
				last_partial <= 0;
			end else begin
				last_partial <= { {(size){1'b0}}, partial_products[size-1] };
			end
		end
	end
endgenerate

// Second level addition: sum the results from stage1
always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		sum_stage2 <= 0;
	end else begin
		if (size >= 2) begin
			if (size % 2 == 0) begin
				sum_stage2 <= sum_reg1[0] + sum_reg1[1];
			end else begin
				// For odd size, add the remaining partial
				sum_stage2 <= sum_reg1[0] + (size % 2 == 1 ? { {(size){1'b0}}, partial_products[size-1] } : 0);
			end
		end else begin
			// For size=1, just assign the single partial product
			sum_stage2 <= partial_products[0];
		end
	end
end

// Assign final output
always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		mul_out <= 0;
	end else begin
		mul_out <= sum_stage2;
	end
end

endmodule

module multi_pipe_4bit#(
    parameter size = 4
)(
    input                     clk         ,   
    input                     rst_n       ,
    input   [size-1:0]        mul_a       ,
    input   [size-1:0]        mul_b       ,
    output  reg [size*2-1:0]  mul_out      
);

parameter N = 2 * size;

// Extend inputs to align with pipeline processing
wire [size:0] a_ext = {1'b0, mul_a}; // 5 bits
wire [size:0] b_ext = {1'b0, mul_b}; // 5 bits

// Generate partial products
reg [N-1:0] partial_products [0:size-1];

integer i;
always @(*) begin
    for (i = 0; i < size; i = i + 1) begin
        if (mul_b[i])
            partial_products[i] = a_ext << i;
        else
            partial_products[i] = {N{1'b0}};
    end
end

// Pipeline registers for partial sums
reg [N-1:0] sum_stage1 [0:size-1];
reg [N-1:0] sum_stage2 [0:size-1];

reg [N-1:0] sum_stage1_next [0:size-1];
reg [N-1:0] sum_stage2_next [0:size-1];

reg [N-1:0] sum_final;

// Stage 1: Add partial products sequentially
always @(*) begin
    // Initialize first register
    sum_stage1_next[0] = partial_products[0];
    // Accumulate partial products
    for (i = 1; i < size; i = i + 1) begin
        sum_stage1_next[i] = sum_stage1[i-1] + partial_products[i];
    end
end

// Stage 2: Registering sum_stage1 to sum_stage2
always @(*) begin
    for (i = 0; i < size; i = i + 1) begin
        sum_stage2_next[i] = sum_stage1[i];
    end
end

// On clock, update pipeline registers
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        for (i = 0; i < size; i = i + 1) begin
            sum_stage1[i] <= {N{1'b0}};
            sum_stage2[i] <= {N{1'b0}};
        end
        sum_final <= {N{1'b0}};
        mul_out <= {(size*2){1'b0}};
    end else begin
        // Update stage 1
        for (i = 0; i < size; i = i + 1) begin
            sum_stage1[i] <= sum_stage1_next[i];
        end
        // Update stage 2
        for (i = 0; i < size; i = i + 1) begin
            sum_stage2[i] <= sum_stage2_next[i];
        end
        // Final output assignment
        sum_final <= sum_stage2[size-1];
        mul_out <= sum_final;
    end
end

endmodule

