wire [size:0] a_ext;
wire [size:0] b_ext;

// Generate extended inputs with zero padding at MSB
assign a_ext = {1'b0, mul_a};
assign b_ext = {1'b0, mul_b};

// Partial products array
reg [N-1:0] partial_products [0:size-1];

// Pipeline registers for partial products
reg [N-1:0] pp_reg [0:size-1];

// Intermediate sum registers for pipeline
reg [N+size-1:0] sum_stage1;
reg [N+size-1:0] sum_stage2;

// Registers for sum pipeline
reg [N+size-1:0] sum_reg1;
reg [N+size-1:0] sum_reg2;

// Final product register
reg [N-1:0] product;

// Generate partial products combinationally
integer i;
always @(*) begin
	for (i = 0; i < size; i = i + 1) begin
		if (b_ext[i]) begin
			partial_products[i] = a_ext << i;
		end else begin
			partial_products[i] = {N{1'b0}};
		end
	end
end

// Sequential logic for pipelining
always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		// Reset all pipeline registers
		for (i = 0; i < size; i = i + 1) begin
			pp_reg[i] <= {N{1'b0}};
		end
		sum_reg1 <= { (N+size){1'b0} };
		sum_reg2 <= { (N+size){1'b0} };
		mul_out <= { (size*2){1'b0} };
	end else begin
		// Stage 1: Register partial products
		for (i = 0; i < size; i = i + 1) begin
			pp_reg[i] <= partial_products[i];
		end
		// Stage 2: Sum partial products
		// Sum all partial products
		sum_stage1 <= { (size){1'b0} };
		for (i = 0; i < size; i = i + 1) begin
			sum_stage1 <= sum_stage1 + { {size{1'b0}}, pp_reg[i] }; // zero-extend for addition
		end
		// Stage 3: Pipeline the sum
		sum_reg1 <= sum_stage1;
		// Final addition to get the product
		sum_reg2 <= sum_reg1;
		product <= sum_reg2[N-1:0]; // lower bits contain the product
