reg [N-1:0] sum_final_stage1, sum_final_stage2;

always @(*) begin
	if (size/2 > 0)
		sum_final_stage1 = sum_pairs_reg[0] + sum_pairs_reg[1];
	else
		sum_final_stage1 = sum_pairs_reg[0];

	if (size/2 > 2) begin
		sum_final_stage2 = sum_final_stage1 + sum_pairs_reg[2];
	end else begin
		sum_final_stage2 = sum_final_stage1;
	end
end

// Register the final sum in pipeline
always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		sum_stage1 <= 0;
		sum_stage2 <= 0;
		mul_out <= 0;
	end else begin
		sum_stage1 <= sum_final_stage1;
		sum_stage2 <= sum_final_stage2;
		mul_out <= sum_final_stage2;
	end
end

endmodule

module multi_pipe_4bit#(
	parameter size = 4
)(
	input 						clk 		,   
	input 						rst_n		,
	input	[size-1:0]			mul_a		,
	input	[size-1:0]			mul_b		,

 	output	reg	[size*2-1:0]	mul_out		
);

parameter N = 2 * size;

// Extend inputs with zeros (not strictly necessary in Verilog, but for clarity)
wire [size-1:0] a_ext = mul_a;
wire [size-1:0] b_ext = mul_b;

// Generate partial products
wire [N-1:0] partial_products [size-1:0];

genvar i;
generate
	for (i = 0; i < size; i = i + 1) begin : gen_partial
		assign partial_products[i] = b_ext[i] ? ({ {size{1'b0}}, a_ext } << i) : {N{1'b0}};
	end
endgenerate

// Pipeline registers for partial products (Stage 1)
reg [N-1:0] partial_reg [size-1:0];

always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		for (i = 0; i < size; i = i + 1) begin
			partial_reg[i] <= {N{1'b0}};
		end
	end else begin
		for (i = 0; i < size; i = i + 1) begin
			partial_reg[i] <= partial_products[i];
		end
	end
end

// Stage 2: Sum the partial products
// First level of addition
reg [N+1:0] sum_level1 [size-2:0];

integer j;
always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		for (j = 0; j < size-1; j = j + 1) begin
			sum_level1[j] <= {N+2{1'b0}};
		end
	end else begin
		for (j = 0; j < size-1; j = j + 1) begin
			if (j == 0)
				sum_level1[j] <= partial_reg[j] + partial_reg[j+1];
			else
				sum_level1[j] <= sum_level1[j-1] + partial_reg[j+1];
		end
	end
end

// Final sum register (Pipeline register for the sum)
reg [N+1:0] sum_reg;

always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		sum_reg <= {N+2{1'b0}};
	end else begin
		if (size > 2) begin
			sum_reg <= sum_level1[size-2] + (size > 3 ? 0 : { { (N+2 - (N+2)) {1'b0} }});
		end else begin
			sum_reg <= sum_level1[0]; // For size=4, only one addition step
		end
	end
end

// Assign output
always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		mul_out <= {size*2{1'b0}};
	end else begin
		mul_out <= sum_reg[N-1:0]; // Take the lower N bits as the final product
	end
end

endmodule

module multi_pipe_4bit#(
	parameter size = 4
)(
	input 						clk 		,   
	input 						rst_n		,
	input	[size-1:0]			mul_a		,
	input	[size-1:0]			mul_b		,

 	output	reg	[size*2-1:0]	mul_out		
);

parameter N = 2 * size;

reg [size-1:0] a_ext;
reg [size-1:0] b_ext;

reg [size-1:0] p0, p1, p2, p3; // Partial products
reg [N:0] sum_stage1; // First addition stage
reg [N:0] sum_stage2; // Second addition stage

reg [N-1:0] sum_reg1; // Pipeline register after first addition
reg [N-1:0] sum_reg2; // Pipeline register after second addition

wire [N-1:0] partial_product [0:3];
wire [N:0] sum1, sum2;

integer i;

// Extend inputs (not strictly necessary, but for clarity)
always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		a_ext <= 0;
		b_ext <= 0;
	end else begin
		a_ext <= mul_a;
		b_ext <= mul_b;
	end
end

// Generate partial products based on bits of mul_b
generate
	for (i = 0; i < size; i = i + 1) begin : gen_partial
		assign partial_product[i] = b_ext[i] ? (a_ext << i) : 0;
	end
endgenerate

// Pipeline stage 1: Add partial products
always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		p0 <= 0;
		p1 <= 0;
		p2 <= 0;
		p3 <= 0;
	end else begin
		p0 <= partial_product[0][size*2-1:0];
		p1 <= partial_product[1][size*2-1:0];
		p2 <= partial_product[2][size*2-1:0];
		p3 <= partial_product[3][size*2-1:0];
	end
end

// First addition stage: sum partial products
assign sum1 = {1'b0, p0} + {1'b0, p1} + {1'b0, p2} + {1'b0, p3};

// Register the result of first addition (pipeline register 1)
always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		sum_reg1 <= 0;
	end else begin
		sum_reg1 <= sum1[N:0]; // Keep only N bits
	end
end

// Second addition stage: sum with shifted partials if needed
// For simplicity, since the partials are already shifted, we can directly assign
// Final sum is just the sum_reg1
always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		sum_reg2 <= 0;
	end else begin
		sum_reg2 <= sum_reg1;
	end
end

// Assign final output
always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		mul_out <= 0;
	end else begin
		mul_out <= sum_reg2[size*2-1:0];
	end
end

endmodule

module multi_pipe_8bit#(
    parameter size = 8
)(
    input clk,
    input rst_n,
    input mul_en_in,
    input [size-1:0] mul_a,
    input [size-1:0] mul_b,
    output reg mul_en_out,
    output reg [2*size-1:0] mul_out
);

// Registers for input data
reg [size-1:0] mul_a_reg;
reg [size-1:0] mul_b_reg;

// Register for enable signal
reg mul_en_out_reg;

// Partial product stages
reg [size-1:0] pp [0:size-1]; // partial products
reg [2*size-1:0] sum [0:size]; // intermediate sums

// Final product register
reg [2*size-1:0] mul_out_reg;

integer i;

// Register inputs and enable signal
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_a_reg <= 0;
        mul_b_reg <= 0;
        mul_en_out_reg <= 0;
    end else begin
        if (mul_en_in) begin
            mul_a_reg <= mul_a;
            mul_b_reg <= mul_b;
        end
        mul_en_out_reg <= mul_en_in;
    end
end

// Compute partial products
generate
    for (i = 0; i < size; i = i + 1) begin : partial_products
        always @(posedge clk or negedge rst_n) begin
            if (!rst_n) begin
                pp[i] <= 0;
            end else if (mul_en_in) begin
                pp[i] <= mul_b_reg[i] ? mul_a_reg : 0;
            end
        end
    end
endgenerate

// Initialize sum[0]
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum[0] <= 0;
    end else if (mul_en_in) begin
        sum[0] <= 0;
    end
end

// Pipeline addition of partial products
// For simplicity, perform sequential addition across stages
// Each stage adds the corresponding partial product shifted appropriately
// and accumulates into sum

// Stage 1 to size to combine partial products
generate
    for (i = 0; i < size; i = i + 1) begin : add_stages
        always @(posedge clk or negedge rst_n) begin
            if (!rst_n) begin
                sum[i+1] <= 0;
            end else if (mul_en_in) begin
                // Shift partial product by i bits
                // Add to previous sum
                sum[i+1] <= sum[i] + ({ { (size){1'b0} }, pp[i] } << i);
            end
        end
    end
endgenerate

// Final output register
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_out_reg <= 0;
        mul_en_out <= 0;
    end else begin
        // When last sum is ready, assign to output
        // The last sum is sum[size]
        mul_out_reg <= sum[size];
        // Propagate enable signal
        mul_en_out <= mul_en_out_reg;
    end
end

// Assign final output
always @(posedge clk) begin
    if (mul_en_out) begin
        mul_out <= mul_out_reg;
    end else begin
        mul_out <= 0;
    end
end

endmodule

module multi_pipe_8bit#(
