        mul_en_out_reg <= 0;
        mul_out <= 0;
        mul_out_reg <= 0;
        sum_stage0 <= 0;
        sum_stage1 <= 0;
        sum_stage2 <= 0;
        sum_stage3 <= 0;
        sum_stage4 <= 0;
        sum_stage5 <= 0;
        sum_stage6 <= 0;
        sum_stage7 <= 0;
    end else begin
