        if (mul_en_in) begin
            for (i = 0; i < size; i = i + 1) begin
                partial_products_reg[i] <= partial_products[i];
            end
        end

        // Stage 1: sum first two partial products
        sum_stage0 <= partial_products_reg[0] + partial_products_reg[1];

        // Stage 2: add next partial product
        sum_stage1 <= sum_stage0 + partial_products_reg[2];

        // Stage 3
        sum_stage2 <= sum_stage1 + partial_products_reg[3];

        // Stage 4
        sum_stage3 <= sum_stage2 + partial_products_reg[4];

