            if (mul_b_reg[i])
                partial_product[i] <= {mul_a_reg, {size{1'b0}}} >> i;
            else
                partial_product[i] <= 0;
        end

        // Stage 1: Sum partial products pairwise
        // For simplicity, sum all partial products in pipeline stages
        // First, sum partial products into sum_stage1
        sum_stage1 <= 0;
        for (i=0; i<size; i=i+1) begin
