        // First stage: sum partial products
        // Initialize sum with first partial product
        if (mul_en_in) begin
            partial_sum <= partial_products[0];
        end else begin
            // Accumulate partial products
            // Sum all partial products
            sum_stage <= 0;
            for (i = 0; i < size; i = i + 1) begin
