                // After falling edge, pulse pattern complete
                state <= 2'b11; // pulse detected state
                data_out <= 1;  // generate output pulse
            end
            2'b11: begin
                // After output pulse, reset to idle
                state <= 2'b00;
                data_out <= 0;
