reg [1:0] state; // 0: idle, 1: rising edge detected, 2: falling edge detected, 3: pulse detected

// State encoding
localparam IDLE = 2'b00;
localparam RISE = 2'b01;
localparam FALL = 2'b10;
localparam DONE = 2'b11;

reg data_in_d1; // delayed data_in for edge detection

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        data_out <= 0;
        data_in_d1 <= 0;
    end else begin
        data_in_d1 <= data_in;

        case (state)
            IDLE: begin
                data_out <= 0;
                if (data_in_d1 == 0 && data_in == 1) begin
                    // Rising edge detected
                    state <= RISE;
                end else begin
                    state <= IDLE;
                end
            end

            RISE: begin
                if (data_in_d1 == 1 && data_in == 0) begin
                    // Falling edge detected after rising edge
                    state <= FALL;
                end else if (data_in == 1) begin
                    // Still high, remain in RISE
                    state <= RISE;
                end else begin
                    // No pattern, reset
                    state <= IDLE;
                end
            end

            FALL: begin
                if (data_in_d1 == 0 && data_in == 0) begin
                    // Pattern 0->1->0 completed
                    data_out <= 1;
                    state <= DONE;
                end else if (data_in == 1) begin
                    // Unexpected change, reset
                    state <= IDLE;
                end else begin
                    // Still low, remain in FALL
                    state <= FALL;
                end
            end

            DONE: begin
                // Generate one-cycle pulse
                data_out <= 1;
                // After one cycle, reset to IDLE
                state <= IDLE;
            end

            default: begin
                state <= IDLE;
            end
        endcase
    end
end

