module pulse_detect(    
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

// State encoding
parameter STATE_IDLE = 2'b00;
parameter STATE_RISE = 2'b01;
parameter STATE_FALL = 2'b10;
parameter STATE_PULSE = 2'b11;

reg [1:0] state, next_state;

// Sequential logic for state transition
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= STATE_IDLE;
        data_out <= 0;
    end else begin
        state <= next_state;
        // Generate data_out: set to 1 only in PULSE state
        if (next_state == STATE_PULSE)
            data_out <= 1;
        else
            data_out <= 0;
    end
end

// Combinational logic for next state
always @(*) begin
    case (state)
        STATE_IDLE: begin
            if (data_in == 1)
                next_state = STATE_RISE;
            else
                next_state = STATE_IDLE;
        end
        STATE_RISE: begin
            if (data_in == 0)
                next_state = STATE_FALL;
            else
                next_state = STATE_RISE;
        end
        STATE_FALL: begin
            if (data_in == 1)
                next_state = STATE_RISE;
            else
                next_state = STATE_PULSE;
        end
        STATE_PULSE: begin
            // After setting output high for one cycle, return to idle
            next_state = STATE_IDLE;
        end
        default: begin
            next_state = STATE_IDLE;
        end
    endcase
end

endmodule

