    wire [31:0] shift_res;
    wire [4:0] shift_amount_a, shift_amount_b;

    wire signed [31:0] a_signed = a;
    wire signed [31:0] b_signed = b;

    // Arithmetic operations
    assign {carry_add, add_res} = {1'b0, a} + {1'b0, b};
    assign {carry_sub, sub_res} = {1'b0, a} - {1'b0, b};
    assign {carry_addu, addu_res} = {1'b0, a} + {1'b0, b}; // same as ADD for unsigned
    assign {carry_subu, subu_res} = {1'b0, a} - {1'b0, b}; // same as SUB for unsigned

    // Overflow detection for signed addition
    assign overflow_add = (~a_signed[31] & ~b_signed[31] & add_res[31]) | (a_signed[31] & b_signed[31] & ~add_res[31]);
    assign overflow_sub = (~a_signed[31] & b_signed[31] & ~sub_res[31]) | (a_signed[31] & ~b_signed[31] & sub_res[31]);
    // For unsigned, carry-out indicates carry
    // For signed, overflow is detected as above

    // Logic operations
    assign logic_res = (aluc == AND) ? (a & b) :
                       (aluc == OR)  ? (a | b) :
                       (aluc == XOR) ? (a ^ b) :
                       (aluc == NOR) ? ~(a | b) :
                       32'bz;

    // Shift amount extraction
    assign shift_amount_a = a[4:0];
    assign shift_amount_b = b[4:0];

    // Shift operations
    assign shift_res = (aluc == SLL)  ? (b << shift_amount_b) :
                       (aluc == SRL)  ? (b >> shift_amount_b) :
                       (aluc == SRA)  ? (b_signed >>> shift_amount_b) :
                       (aluc == SLLV) ? (b << a[4:0]) :
                       (aluc == SRLV) ? (b >> a[4:0]) :
                       (aluc == SRAV) ? (b_signed >>> a[4:0]) :
                       32'bz;

    // LUI operation
    wire [31:0] lui_res = {a[15:0], 16'b0};

    // Default result
    always @(*) begin
        case (aluc)
            ADD: begin
                result = add_res;
                carry_reg = carry_add;
                overflow_reg = overflow_add;
            end
            ADDU: begin
                result = addu_res;
                carry_reg = carry_addu;
                overflow_reg = 1'bz;
            end
            SUB: begin
                result = sub_res;
                carry_reg = carry_sub;
                overflow_reg = overflow_sub;
            end
            SUBU: begin
                result = subu_res;
                carry_reg = carry_subu;
                overflow_reg = 1'bz;
            end
            AND: begin
                result = logic_res;
                carry_reg = 1'bz;
                overflow_reg = 1'bz;
            end
            OR: begin
                result = logic_res;
                carry_reg = 1'bz;
                overflow_reg = 1'bz;
            end
            XOR: begin
                result = logic_res;
                carry_reg = 1'bz;
                overflow_reg = 1'bz;
            end
            NOR: begin
                result = logic_res;
                carry_reg = 1'bz;
                overflow_reg = 1'bz;
            end
            SLT: begin
                result = 32'b0;
                if (a_signed < b_signed)
                    result = 32'b1;
                else
                    result = 32'b0;
                carry_reg = 1'bz;
                overflow_reg = 1'bz;
            end
            SLTU: begin
                result = 32'b0;
                if (a < b)
                    result = 32'b1;
                else
                    result = 32'b0;
                carry_reg = 1'bz;
                overflow_reg = 1'bz;
            end
            SLL, SLLV, SRL, SRLV, SRA, SRAV: begin
                result = shift_res;
                carry_reg = 1'bz;
                overflow_reg = 1'bz;
            end
            LUI: begin
                result = lui_res;
                carry_reg = 1'bz;
                overflow_reg = 1'bz;
            end
            default: begin
                result = 32'bz;
                carry_reg = 1'bz;
                overflow_reg = 1'bz;
            end
        endcase
    end

    assign r = result;

    // Zero flag
    assign zero = (r == 32'b0) ? 1'b1 : 1'b0;

    // Negative flag (sign bit)
    assign negative = r[31];

    // Carry flag (from arithmetic)
    assign carry = carry_reg;

    // Overflow flag (from arithmetic)
    assign overflow = overflow_reg;

    // Flag signal: set to 1 only for SLT and SLTU, else high impedance
    assign flag = (aluc == SLT || aluc == SLTU) ? 1'b1 : 1'bz;

endmodule

