            // Handle state transitions
            case (current_state)
                idle: begin
                    // Transition immediately to s1_red
                    current_state <= s1_red;
                    cnt <= 8'd10; // red duration
                    p_red <= 1'b1;
                    p_yellow <= 1'b0;
                    p_green <= 1'b0;
