                s1_red: begin
                    if (cnt == 0) begin
                        current_state <= s3_green;
                        cnt <= 8'd60; // initial green duration
                        p_red <= 1'b0;
                        p_yellow <= 1'b0;
                        p_green <= 1'b1;
                    end else begin
