                        cnt <= 8'd10; // red duration
                        p_red <= 1'b1;
                        p_yellow <= 1'b0;
                        p_green <= 1'b0;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s3_green: begin
                    if (cnt == 0) begin
                        current_state <= s2_yellow;
                        cnt <= 8'd5; // yellow duration
                        p_red <= 1'b0;
                        p_yellow <= 1'b1;
                        p_green <= 1'b0;
                    end else begin
                        // During green, check for pedestrian request
                        if (pass_request && cnt > 10) begin
                            // Shorten green to 10 cycles
                            cnt <= 10;
                        end else begin
                            cnt <= cnt - 1;
                        end
                    end
                end
                default: begin
                    current_state <= idle;
                end
            endcase
        end
    end

    // Next state logic (handled in clocked process above)

    // Assign lane and sidewalk signals based on current state
    // Lane signals:
    // - green/yellow in lane => sidewalk red
    // - red in lane => sidewalk green
    // For simplicity, assume:
    // lane_red, lane_yellow, lane_green are represented by p_red, p_yellow, p_green
    // sidewalk green when lane red, sidewalk red when lane green/yellow

    wire sidewalk_green, sidewalk_red;

    assign sidewalk_green = p_red; // lane red -> sidewalk green
    assign sidewalk_red = p_green || p_yellow; // lane green/yellow -> sidewalk red

