    // Internal signals for timing durations
    reg [7:0] red_duration;
    reg [7:0] yellow_duration;
    reg [7:0] green_duration;

    // Pedestrian override signal
    wire pedestrian_override;
    assign pedestrian_override = pass_request;

    // Assign clock output
    assign clock = cnt;

    // State transition logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            state <= next_state;
        end
    end

    // Next state and counter logic
    always @(*) begin
        // Default assignments
        next_state = state;
        cnt_next = cnt;

        case (state)
            idle: begin
                next_state = s1_red;
            end

            s1_red: begin
                if (cnt == 0) begin
                    next_state = s3_green;
                end
            end

            s2_yellow: begin
                if (cnt == 0) begin
                    next_state = s1_red;
                end
            end

            s3_green: begin
                if (cnt == 0) begin
                    next_state = s2_yellow;
                end
            end
        endcase
    end

    // Counter control based on state
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd10; // initial value
        end else begin
            case (state)
                idle: begin
                    cnt <= 8'd10; // Not used, but set for completeness
                end

                s1_red: begin
                    if (cnt == 0) begin
                        // Just transitioned from red to green
                        // Set green duration based on pedestrian button
                        if (pedestrian_override && green_duration > 8'd10)
                            green_duration <= 8'd10;
                        else
                            green_duration <= 8'd60;
                        cnt <= green_duration;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end

                s2_yellow: begin
                    if (cnt == 0) begin
                        cnt <= 8'd10; // red duration
                    end else begin
                        cnt <= cnt - 1;
                    end
                end

                s3_green: begin
                    if (cnt == 0) begin
                        cnt <= 8'd5; // yellow duration
                    end else begin
                        cnt <= cnt - 1;
                    end
                end

                default: begin
                    cnt <= 8'd10;
                end
            endcase
        end
    end

    // State-specific signals
    always @(*) begin
        // Default signals
        red = 1'b0;
        yellow = 1'b0;
        green = 1'b0;
    end

    always @(*) begin
        case (state)
            idle: begin
                // Transition to red state
                red = 1'b1;
            end

            s1_red: begin
                red = 1'b1;
            end

            s2_yellow: begin
                yellow = 1'b1;
            end

            s3_green: begin
                green = 1'b1;
            end
        endcase
    end

    // Determine durations based on state
    always @(*) begin
        // Default durations
        red_duration = 8'd10;
        yellow_duration = 8'd5;
        green_duration = 8'd60;

        // Adjust green duration if pedestrian override during green
        if (state == s3_green) begin
            if (pass_request && green_duration > 8'd10)
                green_duration = 8'd10;
            else
                green_duration = 8'd60;
        end
    end

    // Assign the current counter to output
    assign clock = cnt;

    // Initialize state and durations
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            cnt <= 8'd10;
        end else begin
            // Update durations
            case (state)
                s1_red: begin
                    // Duration already handled in counter logic
                end
                s2_yellow: begin
                    // Duration handled in counter logic
                end
                s3_green: begin
                    // Duration handled in counter logic
                end
                default: begin
                    // Set default durations
                end
            endcase
        end
    end

