module traffic_light
    (
        input rst_n,
        input clk,
        input pass_request,
        output wire [7:0] clock,
        output reg red,
        output reg yellow,
        output reg green
    );

    parameter idle = 2'd0,
              s1_red = 2'd1,
              s2_yellow = 2'd2,
              s3_green = 2'd3;

    reg [1:0] state, next_state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;

    // Assign current state outputs
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            cnt <= 8'd10; // initial counter value
            p_red <= 1'b0;
            p_yellow <= 1'b0;
            p_green <= 1'b0;
        end else begin
            state <= next_state;
        end
    end

    // State transition and counter logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd10;
        end else begin
            case (state)
                idle: begin
                    cnt <= 8'd10;
                end
                s1_red: begin
                    if (cnt == 0) begin
                        cnt <= 8'd10; // default duration for red
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s2_yellow: begin
                    if (cnt == 0) begin
                        cnt <= 8'd5; // yellow duration
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s3_green: begin
                    if (cnt == 0) begin
                        cnt <= 8'd60; // default green duration
                    end else begin
                        // Adjust green duration if pedestrian button pressed
                        if (pass_request && cnt > 10) begin
                            cnt <= 8'd10;
                        end else begin
                            cnt <= cnt - 1;
                        end
                    end
                end
                default: cnt <= 8'd10;
            endcase
        end
    end

    // Next state logic
    always @(*) begin
        case (state)
            idle: next_state = s1_red;
            s1_red: begin
                if (cnt == 0)
                    next_state = s3_green;
                else
                    next_state = s1_red;
            end
            s2_yellow: begin
                if (cnt == 0)
                    next_state = s1_red;
                else
                    next_state = s2_yellow;
            end
            s3_green: begin
                if (cnt == 0)
                    next_state = s2_yellow;
                else
                    next_state = s3_green;
            end
            default: next_state = idle;
        endcase
    end

    // Output signal control based on state
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red <= 1'b0;
            yellow <= 1'b0;
            green <= 1'b0;
        end else begin
            case (state)
                idle: begin
                    red <= 1'b0;
                    yellow <= 1'b0;
                    green <= 1'b0;
                end
                s1_red: begin
                    red <= 1'b1;
                    yellow <= 1'b0;
                    green <= 1'b0;
                end
                s2_yellow: begin
                    red <= 1'b0;
                    yellow <= 1'b1;
                    green <= 1'b0;
                end
                s3_green: begin
                    red <= 1'b0;
                    yellow <= 1'b0;
                    green <= 1'b1;
                end
                default: begin
                    red <= 1'b0;
                    yellow <= 1'b0;
                    green <= 1'b0;
                end
            endcase
        end
    end

    // Assign the clock output
    assign clock = cnt;

    // Determine sidewalk light based on lane signals
    wire sidewalk_red, sidewalk_green;
    assign sidewalk_red = (green) ? 1'b0 : 1'b1; // sidewalk red when lane green/yellow
    assign sidewalk_green = (red) ? 1'b1 : 1'b0; // sidewalk green when lane red

endmodule

module width_8to16(
	input 				   clk 		,   
	input 				   rst_n		,
	input				      valid_in	,
	input	   [7:0]		   data_in	,

 	output	reg			valid_out,
	output   reg [15:0]	data_out
);

reg [7:0] data_lock;        // Stores the first data byte
reg       data_valid;       // Indicates if first data has been stored

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        data_lock   <= 8'b0;
        data_valid  <= 1'b0;
        data_out    <= 16'b0;
        valid_out   <= 1'b0;
    end else begin
        if (valid_in) begin
            if (!data_valid) begin
                // Store the first data byte
                data_lock  <= data_in;
                data_valid <= 1'b1;
                valid_out  <= 1'b0; // Not yet valid output
            end else begin
                // Concatenate second data and output
                data_out   <= {data_lock, data_in};
                valid_out  <= 1'b1;
                data_valid <= 1'b0; // Reset for next pair
            end
        end else begin
            // If no valid input, keep valid_out low
            valid_out <= 1'b0;
        end
    end
end

